export namespace SessionRetry {
  export const RETRY_INITIAL_DELAY = 2000
  export const RETRY_BACKOFF_FACTOR = 2
  export const RETRY_MAX_DELAY_NO_HEADERS = 30_000
  export const RETRY_MAX_DELAY = 2_147_483_647

  export async function sleep(ms: number, signal: AbortSignal): Promise<void> {
    return new Promise((resolve, reject) => {
      const abortHandler = () => {
        clearTimeout(timeout)
        reject(new DOMException("Aborted", "AbortError"))
      }
      const timeout = setTimeout(
        () => {
          signal.removeEventListener("abort", abortHandler)
          resolve()
        },

      Math.min(ms, RETRY_MAX_DELAY),
    )
    signal.addEventListener("abort", abortHandler, { once: true })
  })
}

export function delay(attempt: number, error?: MessageV2.APIError) {
  if (error) {
    const headers = error.data.responseHeaders
    if (headers) {
      const retryAfterMs = headers["retry-after-ms"]
      if (retryAfterMs) {
        const parsedMs = Number.parseFloat(retryAfterMs)
        if (!Number.isNaN(parsedMs)) {
          return parsedMs
        }
      }

      const retryAfter = headers["retry-after"]
      if (retryAfter) {

        const parsedSeconds = Number.parseFloat(retryAfter)
        if (!Number.isNaN(parsedSeconds)) {
          return Math.ceil(parsedSeconds * 1000)
        }
        const parsed = Date.parse(retryAfter) - Date.now()
        if (!Number.isNaN(parsed) && parsed > 0) {
          return Math.ceil(parsed)
        }
      }

      return RETRY_INITIAL_DELAY * Math.pow(RETRY_BACKOFF_FACTOR, attempt - 1)
    }
  }

  return Math.min(RETRY_INITIAL_DELAY * Math.pow(RETRY_BACKOFF_FACTOR, attempt - 1), RETRY_MAX_DELAY_NO_HEADERS)
}

export function retryable(error: ReturnType<NamedError["toObject"]>) {
  if (MessageV2.APIError.isInstance(error)) {
    if (!error.data.isRetryable) return undefined

  return error.data.message.includes("Overloaded") ? "Provider is overloaded" : error.data.message
}

if (typeof error.data?.message === "string") {
  try {
    const json = JSON.parse(error.data.message)
    if (json.type === "error" && json.error?.type === "too_many_requests") {
      return "Too Many Requests"
    }
    if (json.code.includes("exhausted") || json.code.includes("unavailable")) {
      return "Provider is overloaded"
    }
    if (json.type === "error" && json.error?.code?.includes("rate_limit")) {
      return "Rate Limited"
    }
    if (
      json.error?.message?.includes("no_kv_space") ||
      (json.type === "error" && json.error?.type === "server_error") ||
      !!json.error
    ) {

          return "Provider Server Error"
        }
      } catch {}
    }

    return undefined
  }
}

export type RevertInput = z.infer<typeof RevertInput>

export async function revert(input: RevertInput) {
  SessionPrompt.assertNotBusy(input.sessionID)
  const all = await Session.messages({ sessionID: input.sessionID })
  let lastUser: MessageV2.User | undefined
  const session = await Session.get(input.sessionID)

  let revert: Session.Info["revert"]
  const patches: Snapshot.Patch[] = []
  for (const msg of all) {
    if (msg.info.role === "user") lastUser = msg.info
    const remaining = []
    for (const part of msg.parts) {
      if (revert) {
        if (part.type === "patch") {
          patches.push(part)
        }
        continue
      }

    if (!revert) {
      if ((msg.info.id === input.messageID && !input.partID) || part.id === input.partID) {
        const partID = remaining.some((item) => ["text", "tool"].includes(item.type)) ? input.partID : undefined
        revert = {
          messageID: !partID && lastUser ? lastUser.id : msg.info.id,
          partID,
        }
      }
      remaining.push(part)
    }
  }
}

if (revert) {
  const session = await Session.get(input.sessionID)
  revert.snapshot = session.revert?.snapshot ?? (await Snapshot.track())
  await Snapshot.revert(patches)
  if (revert.snapshot) revert.diff = await Snapshot.diff(revert.snapshot)
  const rangeMessages = all.filter((msg) => msg.info.id >= revert!.messageID)

    const diffs = await SessionSummary.computeDiff({ messages: rangeMessages })
    await Storage.write(["session_diff", input.sessionID], diffs)
    Bus.publish(Session.Event.Diff, {
      sessionID: input.sessionID,
      diff: diffs,
    })
    return Session.update(input.sessionID, (draft) => {
      draft.revert = revert
      draft.summary = {
        additions: diffs.reduce((sum, x) => sum + x.additions, 0),
        deletions: diffs.reduce((sum, x) => sum + x.deletions, 0),
        files: diffs.length,
      }
    })
  }
  return session
}

export async function unrevert(input: { sessionID: string }) {
  log.info("unreverting", input)

  SessionPrompt.assertNotBusy(input.sessionID)
  const session = await Session.get(input.sessionID)
  if (!session.revert) return session
  if (session.revert.snapshot) await Snapshot.restore(session.revert.snapshot)
  const next = await Session.update(input.sessionID, (draft) => {
    draft.revert = undefined
  })
  return next
}

export async function cleanup(session: Session.Info) {
  if (!session.revert) return
  const sessionID = session.id
  let msgs = await Session.messages({ sessionID })
  const messageID = session.revert.messageID
  const [preserve, remove] = splitWhen(msgs, (x) => x.info.id === messageID)
  msgs = preserve
  for (const msg of remove) {
    await Storage.remove(["message", sessionID, msg.info.id])
    await Bus.publish(MessageV2.Event.Removed, { sessionID: sessionID, messageID: msg.info.id })

    }
    const last = preserve.at(-1)
    if (session.revert.partID && last) {
      const partID = session.revert.partID
      const [preserveParts, removeParts] = splitWhen(last.parts, (x) => x.id === partID)
      last.parts = preserveParts
      for (const part of removeParts) {
        await Storage.remove(["part", last.info.id, part.id])
        await Bus.publish(MessageV2.Event.PartRemoved, {
          sessionID: sessionID,
          messageID: last.info.id,
          partID: part.id,
        })
      }
    }
    await Session.update(sessionID, (draft) => {
      draft.revert = undefined
    })
  }
}

