    pending.delete(key)

    return fetch(`${URL}/share_sync`, {
      method: "POST",
      body: JSON.stringify({
        sessionID: sessionID,
        secret,
        key: key,
        content,
      }),
    })
  })
  .then((x) => {
    if (x) {

