async newSession(params: NewSessionRequest) {
  const directory = params.cwd
  try {
    const model = await defaultModel(this.config, directory)

    // Store ACP session state
    const state = await this.sessionManager.create(params.cwd, params.mcpServers, model)
    const sessionId = state.id

    log.info("creating_session", { sessionId, mcpServers: params.mcpServers.length })

    const load = await this.loadSessionMode({
      cwd: directory,
      mcpServers: params.mcpServers,
      sessionId,

    })

    return {
      sessionId,
      models: load.models,
      modes: load.modes,
      _meta: {},
    }
  } catch (e) {
    const error = MessageV2.fromError(e, {
      providerID: this.config.defaultModel?.providerID ?? "unknown",
    })
    if (LoadAPIKeyError.isInstance(error)) {
      throw RequestError.authRequired()
    }
    throw e
  }
}

async loadSession(params: LoadSessionRequest) {

const directory = params.cwd
const sessionId = params.sessionId

try {
  const model = await defaultModel(this.config, directory)

  // Store ACP session state
  await this.sessionManager.load(sessionId, params.cwd, params.mcpServers, model)

  log.info("load_session", { sessionId, mcpServers: params.mcpServers.length })

  const result = await this.loadSessionMode({
    cwd: directory,
    mcpServers: params.mcpServers,
    sessionId,
  })

  // Replay session history
  const messages = await this.sdk.session
    .messages(

    {
      sessionID: sessionId,
      directory,
    },
    { throwOnError: true },
  )
  .then((x) => x.data)
  .catch((err) => {
    log.error("unexpected error when fetching message", { error: err })
    return undefined
  })

const lastUser = messages?.findLast((m) => m.info.role === "user")?.info
if (lastUser?.role === "user") {
  result.models.currentModelId = `${lastUser.model.providerID}/${lastUser.model.modelID}`
  this.sessionManager.setModel(sessionId, {
    providerID: lastUser.model.providerID,
    modelID: lastUser.model.modelID,
  })
  if (result.modes.availableModes.some((m) => m.id === lastUser.agent)) {

      result.modes.currentModeId = lastUser.agent
      this.sessionManager.setMode(sessionId, lastUser.agent)
    }
  }

  for (const msg of messages ?? []) {
    log.debug("replay message", msg)
    await this.processMessage(msg)
  }

  return result
} catch (e) {
  const error = MessageV2.fromError(e, {
    providerID: this.config.defaultModel?.providerID ?? "unknown",
  })
  if (LoadAPIKeyError.isInstance(error)) {
    throw RequestError.authRequired()
  }
  throw e
}

}

private async processMessage(message: SessionMessageResponse) {
  log.debug("process message", message)
  if (message.info.role !== "assistant" && message.info.role !== "user") return
  const sessionId = message.info.sessionID

  for (const part of message.parts) {
    if (part.type === "tool") {
      switch (part.state.status) {
        case "pending":
          await this.connection
            .sessionUpdate({
              sessionId,
              update: {
                sessionUpdate: "tool_call",
                toolCallId: part.callID,
                title: part.tool,
                kind: toToolKind(part.tool),
                status: "pending",

        locations: [],
        rawInput: {},
      },
    })
    .catch((err) => {
      log.error("failed to send tool pending to ACP", { error: err })
    })
  break
case "running":
  await this.connection
    .sessionUpdate({
      sessionId,
      update: {
        sessionUpdate: "tool_call_update",
        toolCallId: part.callID,
        status: "in_progress",
        kind: toToolKind(part.tool),
        title: part.tool,
        locations: toLocations(part.tool, part.state.input),
        rawInput: part.state.input,

      },
    })
    .catch((err) => {
      log.error("failed to send tool in_progress to ACP", { error: err })
    })
  break
case "completed":
  const kind = toToolKind(part.tool)
  const content: ToolCallContent[] = [
    {
      type: "content",
      content: {
        type: "text",
        text: part.state.output,
      },
    },
  ]

  if (kind === "edit") {
    const input = part.state.input

  const filePath = typeof input["filePath"] === "string" ? input["filePath"] : ""
  const oldText = typeof input["oldString"] === "string" ? input["oldString"] : ""
  const newText =
    typeof input["newString"] === "string"
      ? input["newString"]
      : typeof input["content"] === "string"
        ? input["content"]
        : ""
  content.push({
    type: "diff",
    path: filePath,
    oldText,
    newText,
  })
}

if (part.tool === "todowrite") {
  const parsedTodos = z.array(Todo.Info).safeParse(JSON.parse(part.state.output))
  if (parsedTodos.success) {
    await this.connection

    .sessionUpdate({
      sessionId,
      update: {
        sessionUpdate: "plan",
        entries: parsedTodos.data.map((todo) => {
          const status: PlanEntry["status"] =
            todo.status === "cancelled" ? "completed" : (todo.status as PlanEntry["status"])
          return {
            priority: "medium",
            status,
            content: todo.content,
          }
        }),
      },
    })
    .catch((err) => {
      log.error("failed to send session update for todo", { error: err })
    })
} else {
  log.error("failed to parse todo output", { error: parsedTodos.error })

  }
}

await this.connection
  .sessionUpdate({
    sessionId,
    update: {
      sessionUpdate: "tool_call_update",
      toolCallId: part.callID,
      status: "completed",
      kind,
      content,
      title: part.state.title,
      rawInput: part.state.input,
      rawOutput: {
        output: part.state.output,
        metadata: part.state.metadata,
      },
    },
  })

    .catch((err) => {
      log.error("failed to send tool completed to ACP", { error: err })
    })
  break
case "error":
  await this.connection
    .sessionUpdate({
      sessionId,
      update: {
        sessionUpdate: "tool_call_update",
        toolCallId: part.callID,
        status: "failed",
        kind: toToolKind(part.tool),
        title: part.tool,
        rawInput: part.state.input,
        content: [
          {
            type: "content",
            content: {
              type: "text",

                  text: part.state.error,
                },
              },
            ],
            rawOutput: {
              error: part.state.error,
            },
          },
        })
        .catch((err) => {
          log.error("failed to send tool error to ACP", { error: err })
        })
      break
  }
} else if (part.type === "text") {
  if (part.text) {
    const audience: Role[] | undefined = part.synthetic ? ["assistant"] : part.ignored ? ["user"] : undefined
    await this.connection
      .sessionUpdate({
        sessionId,

        update: {
          sessionUpdate: message.info.role === "user" ? "user_message_chunk" : "agent_message_chunk",
          content: {
            type: "text",
            text: part.text,
            ...(audience && { annotations: { audience } }),
          },
        },
      })
      .catch((err) => {
        log.error("failed to send text to ACP", { error: err })
      })
  }
} else if (part.type === "file") {
  // Replay file attachments as appropriate ACP content blocks.
  // Nikcli stores files internally as { type: "file", url, filename, mime }.
  // We convert these back to ACP blocks based on the URL scheme and MIME type:
  // - file:// URLs → resource_link
  // - data: URLs with image/* → image block
  // - data: URLs with text/* or application/json → resource with text

// - data: URLs with other types → resource with blob
const url = part.url
const filename = part.filename ?? "file"
const mime = part.mime || "application/octet-stream"
const messageChunk = message.info.role === "user" ? "user_message_chunk" : "agent_message_chunk"

if (url.startsWith("file://")) {
  // Local file reference - send as resource_link
  await this.connection
    .sessionUpdate({
      sessionId,
      update: {
        sessionUpdate: messageChunk,
        content: { type: "resource_link", uri: url, name: filename, mimeType: mime },
      },
    })
    .catch((err) => {
      log.error("failed to send resource_link to ACP", { error: err })
    })
} else if (url.startsWith("data:")) {

// Embedded content - parse data URL and send as appropriate block type
const base64Match = url.match(/^data:([^;]+);base64,(.*)$/)
const dataMime = base64Match?.[1]
const base64Data = base64Match?.[2] ?? ""

const effectiveMime = dataMime || mime

if (effectiveMime.startsWith("image/")) {
  // Image - send as image block
  await this.connection
    .sessionUpdate({
      sessionId,
      update: {
        sessionUpdate: messageChunk,
        content: {
          type: "image",
          mimeType: effectiveMime,
          data: base64Data,
          uri: `file://${filename}`,
        },

      },
    })
    .catch((err) => {
      log.error("failed to send image to ACP", { error: err })
    })
} else {
  // Non-image: text types get decoded, binary types stay as blob
  const isText = effectiveMime.startsWith("text/") || effectiveMime === "application/json"
  const resource = isText
    ? {
        uri: `file://${filename}`,
        mimeType: effectiveMime,
        text: Buffer.from(base64Data, "base64").toString("utf-8"),
      }
    : { uri: `file://${filename}`, mimeType: effectiveMime, blob: base64Data }

  await this.connection
    .sessionUpdate({
      sessionId,
      update: {

            sessionUpdate: messageChunk,
            content: { type: "resource", resource },
          },
        })
        .catch((err) => {
          log.error("failed to send resource to ACP", { error: err })
        })
    }
  }
  // URLs that don't match file:// or data: are skipped (unsupported)
} else if (part.type === "reasoning") {
  if (part.text) {
    await this.connection
      .sessionUpdate({
        sessionId,
        update: {
          sessionUpdate: "agent_thought_chunk",
          content: {
            type: "text",
            text: part.text,

              },
            },
          })
          .catch((err) => {
            log.error("failed to send reasoning to ACP", { error: err })
          })
      }
    }
  }
}

private async loadSessionMode(params: LoadSessionRequest) {
  const directory = params.cwd
  const model = await defaultModel(this.config, directory)
  const sessionId = params.sessionId

  const providers = await this.sdk.config.providers({ directory }).then((x) => x.data!.providers)
  const entries = providers.sort((a, b) => {
    const nameA = a.name.toLowerCase()
    const nameB = b.name.toLowerCase()

  if (nameA < nameB) return -1
  if (nameA > nameB) return 1
  return 0
})
const availableModels = entries.flatMap((provider) => {
  const models = Provider.sort(Object.values(provider.models))
  return models.map((model) => ({
    modelId: `${provider.id}/${model.id}`,
    name: `${provider.name}/${model.name}`,
  }))
})

const agents = await this.config.sdk.app
  .agents(
    {
      directory,
    },
    { throwOnError: true },
  )
  .then((resp) => resp.data!)

const commands = await this.config.sdk.command
  .list(
    {
      directory,
    },
    { throwOnError: true },
  )
  .then((resp) => resp.data!)

const availableCommands = commands.map((command) => ({
  name: command.name,
  description: command.description ?? "",
}))
const names = new Set(availableCommands.map((c) => c.name))
if (!names.has("compact"))
  availableCommands.push({
    name: "compact",
    description: "compact the session",
  })

const availableModes = agents
  .filter((agent) => agent.mode !== "subagent" && !agent.hidden)
  .map((agent) => ({
    id: agent.name,
    name: agent.name,
    description: agent.description,
  }))

const defaultAgentName = await AgentModule.defaultAgent()
const currentModeId = availableModes.find((m) => m.name === defaultAgentName)?.id ?? availableModes[0].id

// Persist the default mode so prompt() uses it immediately
this.sessionManager.setMode(sessionId, currentModeId)

const mcpServers: Record<string, Config.Mcp> = {}
for (const server of params.mcpServers) {
  if ("type" in server) {
    mcpServers[server.name] = {
      url: server.url,

      headers: server.headers.reduce<Record<string, string>>((acc, { name, value }) => {
        acc[name] = value
        return acc
      }, {}),
      type: "remote",
    }
  } else {
    mcpServers[server.name] = {
      type: "local",
      command: [server.command, ...server.args],
      environment: server.env.reduce<Record<string, string>>((acc, { name, value }) => {
        acc[name] = value
        return acc
      }, {}),
    }
  }
}

await Promise.all(
  Object.entries(mcpServers).map(async ([key, mcp]) => {

    await this.sdk.mcp
      .add(
        {
          directory,
          name: key,
          config: mcp,
        },
        { throwOnError: true },
      )
      .catch((error) => {
        log.error("failed to add mcp server", { name: key, error })
      })
  }),
)

setTimeout(() => {
  this.connection.sessionUpdate({
    sessionId,
    update: {
      sessionUpdate: "available_commands_update",

        availableCommands,
      },
    })
  }, 0)

  return {
    sessionId,
    models: {
      currentModelId: `${model.providerID}/${model.modelID}`,
      availableModels,
    },
    modes: {
      availableModes,
      currentModeId,
    },
    _meta: {},
  }
}

